// n8n Code node "Plan the Searches" in "Reel Factory: Find References" (mode: Run Once for All Items).
// Reads "Load Bot Users" (dtj_bot_users), "Load Watchlist" (dtj_reel_watchlist), "Load Audiences" (dtj_reel_audiences) and, when
// the reel bot started the run, "From the Telegram Bot" (query, sources, limit, requested_by, chat_id; for an audience scan also
// mode "audience", audience, hashtags, creators). Output: one item per Apify call { kind, mode, label, query, source, actor, input,
// max_items, keep_n, max_usd, timeout_s, brand, niche, audience, slug, chat_ids, found_for }, or for a request that cannot be
// searched one { chat_id, text, summary: true } item for "Send the Summary" (no actor: nothing is called).
// kind "refs" (reference videos, Keep / Skip) or, for an audience scan (Harsh, 25 Oct 2026: "analyze what type of content holds
// them the longest, whats the trend going on insta"): "audience" (top reels of the audience's hashtags and creators), "profiles"
// (the creators' follower counts, for views per follower) and "trending" (India's trending Reels audio).
// The actors were picked on 25 Oct 2026 from their Apify Store pages (price per result, a direct video link in the output);
// each gets a 3-result live test once the "DTJ Apify" credential exists:
//   instagram  apify/instagram-reel-scraper (a profile) / apify/instagram-hashtag-scraper (a hashtag, resultsType reels)
//   pinterest  apt_marble/pinterest-video-scraper (video pins only, mp4Url)
//   meta       automation-lab/facebook-ads-library (country IN, active, video; startDate -> days running)
//   audience   the two Instagram actors above; followers from apify/instagram-profile-scraper ($2.60 per 1,000 profiles);
//              trending audio from s_actors/instagram-trending-audio (country IN, no keyword: $1.99 per 1,000 sounds, plus
//              $0.34 once a day when its Indian list is built; seemuapps/instagram-music-scraper $8 / 1,000 and
//              memo23/instagram-audio-scraper $4 / 1,000 need a song or keyword and have no per-country flag)
// Fallbacks whose output "Read the Results" also reads: apify/instagram-scraper, silentflow/pinterest-scraper-ppr,
// apify/facebook-ads-scraper.
const MAX_PER_SOURCE = 10, DEFAULT_PER_SOURCE = 5, MAX_CALLS = 60;
const MAX_USD = 0.10;        // Apify's charge cap per call (maxTotalChargeUsd); 10 results cost about $0.03-0.04
const MAX_AUDIENCE = 30, AUDIENCE_SOURCES = 10;   // an audience scan: reels per hashtag or creator, hashtags + creators
const AUDIENCE_USD = 0.15, TRENDING_USD = 0.50;      // 30 reels cost about $0.08; the trending list up to $0.36 on its first run of the day
const META_POOL = 3;         // ads are fetched 3x the limit and the longest running ones kept (Meta cannot sort by run time)
const SOURCES = ['instagram', 'pinterest', 'meta'];
const ALIASES = { instagram: 'instagram', insta: 'instagram', ig: 'instagram', reels: 'instagram', pinterest: 'pinterest', pin: 'pinterest',
  pins: 'pinterest', meta: 'meta', fb: 'meta', facebook: 'meta', ads: 'meta', ad: 'meta', adlibrary: 'meta', all: 'all' };
const clean = (s) => String(s == null ? '' : s).trim();
// @mamaearth.in -> "mamaearth": a handle's .in / _official / .india / _store ending is not part of the brand's name
const words = (s) => clean(s).replace(/^[@#]/, '').replace(/[._](in|india|official|store|shop|co)$/i, '').replace(/[._]+/g, ' ').replace(/\s+/g, ' ').trim();
const num = (v, d) => { const n = parseInt(String(v == null ? '' : v), 10); return Number.isFinite(n) && n > 0 ? Math.min(n, MAX_PER_SOURCE) : d; };

// a list given as an array, a JSON array or text with commas, spaces or new lines
const list = (v) => {
  if (Array.isArray(v)) return v.map(clean).filter(Boolean);
  const t = clean(v);
  if (t.startsWith('[')) { try { const a = JSON.parse(t); if (Array.isArray(a)) return a.map(clean).filter(Boolean); } catch (e) { /* as text */ } }
  return t.split(/[\s,;]+/).map(clean).filter(Boolean);
};
const hashtagsOf = (v) => [...new Set(list(v).map((h) => h.replace(/^#/, '').toLowerCase()).filter((h) => /^[\p{L}\p{N}_]{2,100}$/u.test(h)))];
const creatorsOf = (v) => [...new Set(list(v).map((c) => { const m = c.match(/instagram\.com\/([A-Za-z0-9._]{1,30})/i); return (m ? m[1] : c.replace(/^@/, '')).toLowerCase(); })
  .filter((c) => /^[a-z0-9._]{1,30}$/.test(c)))];
const slugOf = (s) => clean(s).toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60);

// an audience scan: the top reels of each hashtag and creator, the creators' followers, India's trending audio
function audienceCalls(a, n, base) {
  const hashtags = hashtagsOf(a.hashtags), creators = creatorsOf(a.creators);
  const both = [...hashtags.map((h) => ({ h })), ...creators.map((c) => ({ c }))].slice(0, AUDIENCE_SOURCES);
  const common = { ...base, label: clean(a.audience), audience: clean(a.audience).slice(0, 100), slug: slugOf(a.slug || a.audience),
    source: 'audience', brand: '', niche: '' };
  const out = both.map((x) => (x.h
    ? { ...common, kind: 'audience', query: '#' + x.h, actor: 'apify/instagram-hashtag-scraper',
      input: { hashtags: [x.h], resultsType: 'reels', resultsLimit: n }, max_items: n, keep_n: n, max_usd: AUDIENCE_USD }
    : { ...common, kind: 'audience', query: '@' + x.c, actor: 'apify/instagram-reel-scraper',
      input: { username: [x.c], resultsLimit: n, skipPinnedPosts: true }, max_items: n, keep_n: n, max_usd: AUDIENCE_USD }));
  const asked = both.filter((x) => x.c).map((x) => x.c);
  if (asked.length) {
    out.push({ ...common, kind: 'profiles', query: asked.map((c) => '@' + c).join(' '), actor: 'apify/instagram-profile-scraper',
      input: { usernames: asked }, max_items: asked.length, keep_n: 0, max_usd: MAX_USD });
  }
  if (out.length) {
    const sounds = Math.min(n, MAX_PER_SOURCE);
    out.push({ ...common, kind: 'trending', source: 'trending_audio', query: 'trending Reels audio, India', actor: 's_actors/instagram-trending-audio',
      input: { countries: ['IN'], maxSounds: sounds, trendingOnly: true, soundType: 'all', topReels: 1 }, max_items: sounds, keep_n: sounds,
      max_usd: TRENDING_USD });
  }
  return out;
}

// what to search for one brand or query: { instagram: {handle} | {hashtag}, pinterest: 'words', meta: {query} | {page} | {library} }
function targets(row) {
  const t = {};
  const ig = clean(row.instagram);
  const igUrl = ig.match(/instagram\.com\/(?:explore\/tags\/([A-Za-z0-9_]+)|([A-Za-z0-9._]{1,30}))/i);
  if (igUrl) t.instagram = igUrl[1] ? { hashtag: igUrl[1] } : { handle: igUrl[2] };
  else if (/^#[\p{L}\p{N}_]{2,}$/u.test(ig)) t.instagram = { hashtag: ig.slice(1) };
  else if (/^@?[A-Za-z0-9._]{1,30}$/.test(ig)) t.instagram = { handle: ig.replace(/^@/, '') };
  if (clean(row.pinterest_query)) t.pinterest = clean(row.pinterest_query).slice(0, 100);
  const meta = clean(row.meta_advertiser);
  if (/^https:\/\/(www\.)?facebook\.com\/ads\/library\//i.test(meta)) t.meta = { library: meta };
  else if (/^https:\/\/(www\.)?facebook\.com\/[^\s]+$/i.test(meta)) t.meta = { page: meta };
  else if (meta) t.meta = { query: meta.slice(0, 100) };
  return t;
}

// the search in words, for the library's query column and the digest
const said = (source, t) => source === 'pinterest' ? t : t.handle ? '@' + t.handle : t.hashtag ? '#' + t.hashtag : t.library || t.page || t.query;

function call(source, target, n) {
  if (source === 'instagram') {
    return target.hashtag
      ? { actor: 'apify/instagram-hashtag-scraper', input: { hashtags: [target.hashtag], resultsType: 'reels', resultsLimit: n }, max_items: n }
      : { actor: 'apify/instagram-reel-scraper', input: { username: [target.handle], resultsLimit: n, skipPinnedPosts: true }, max_items: n };
  }
  if (source === 'pinterest') {
    return { actor: 'apt_marble/pinterest-video-scraper', input: { queries: [target], maxVideos: n, excludePromoted: false }, max_items: n };
  }
  const pool = Math.min(n * META_POOL, MAX_PER_SOURCE * META_POOL);
  const input = { country: 'IN', activeStatus: 'active', mediaType: 'video', maxAds: pool };
  if (target.library) input.adsLibraryUrls = [target.library];
  else if (target.page) input.pageUrls = [target.page];
  else input.searchQueries = [target.query];
  return { actor: 'automation-lab/facebook-ads-library', input, max_items: pool };
}

const rows = (name) => { try { return $(name).all().map((i) => i.json || {}); } catch (e) { return []; } };
const users = rows('Load Bot Users');
const audiences = rows('Load Audiences').filter((r) => r.audience);
let bot = null;
try { bot = $('From the Telegram Bot').first().json; } catch (e) { bot = null; }  // the weekly scan
const watch = rows('Load Watchlist').filter((r) => r.brand || r.instagram || r.pinterest_query || r.meta_advertiser);

const plans = [];
if (bot && clean(bot.mode).toLowerCase() === 'audience') {
  const chat = clean(bot.chat_id);
  if (!chat) return [];
  const name = clean(bot.audience).slice(0, 100);
  const saved = audiences.find((r) => clean(r.audience).toLowerCase() === name.toLowerCase() || clean(r.slug) === slugOf(name)) || {};
  const given = list(bot.hashtags).length || list(bot.creators).length;
  const a = given ? { audience: name, slug: saved.slug, hashtags: bot.hashtags, creators: bot.creators } : saved;
  const v = parseInt(clean(bot.limit) || clean(saved.per_source), 10);
  const n = Number.isFinite(v) && v > 0 ? Math.min(v, MAX_AUDIENCE) : MAX_AUDIENCE;
  if (name) plans.push(...audienceCalls({ ...a, audience: name }, n, { mode: 'bot', chat_ids: [chat], found_for: clean(bot.requested_by) || 'the bot' }));
  if (!plans.length) {
    return [{ json: { chat_id: chat, summary: true, text: 'An audience scan needs the audience (for example "Gen Z urban India") and at least one '
      + 'hashtag or @creator, or the name of an audience saved in dtj_reel_audiences.' } }];
  }
} else if (bot) {
  const chat = clean(bot.chat_id);
  const query = clean(bot.query).slice(0, 200);
  const asked = clean(bot.sources).toLowerCase().split(/[\s,;/+]+/).filter(Boolean);
  const unknown = asked.filter((s) => !ALIASES[s]);
  let sources = asked.length ? [...new Set(asked.map((s) => ALIASES[s]).filter(Boolean))] : ['all'];
  if (sources.includes('all')) sources = SOURCES.slice();
  const help = (why) => [{ json: { chat_id: chat, summary: true, text: why + '\n\nUse: /refs @handle, /refs #hashtag, /refs a brand on the '
    + 'watchlist, or /refs some words; add instagram, pinterest or meta to search only those, and a number (at most '
    + MAX_PER_SOURCE + ') for how many per source. Example: /refs @mamaearth.in meta 5' } }];
  if (!chat) return [];
  if (!query) return help('What should I search for?');
  if (unknown.length || !sources.length) return help('I do not know the source ' + unknown.join(', ') + '.');
  const lower = query.toLowerCase().replace(/^@/, '');
  const row = watch.find((r) => clean(r.brand).toLowerCase() === lower || clean(r.instagram).toLowerCase().replace(/^@/, '') === lower);
  let t;
  if (row) t = targets(row);
  else {
    const isUrl = /^https:\/\//i.test(query);
    t = targets({ instagram: isUrl ? (/instagram\.com/i.test(query) ? query : '') : query.startsWith('#') ? query : query.startsWith('@') ? query
      : '#' + query.toLowerCase().replace(/[^\p{L}\p{N}_]+/gu, ''),
      pinterest_query: isUrl ? '' : words(query), meta_advertiser: isUrl ? (/facebook\.com/i.test(query) ? query : '') : words(query) });
  }
  const n = num(bot.limit, row ? num(row.per_source, DEFAULT_PER_SOURCE) : DEFAULT_PER_SOURCE);
  const missing = sources.filter((s) => !t[s]);
  for (const s of sources.filter((x) => t[x])) {
    plans.push({ kind: 'refs', mode: 'bot', label: query, query: said(s, t[s]), source: s, ...call(s, t[s], n), keep_n: n, brand: row ? clean(row.brand) : '',
      niche: row ? clean(row.niche) : '', chat_ids: [chat], found_for: clean(bot.requested_by) || 'the bot', skipped: missing });
  }
  if (!plans.length) return help('I could not turn "' + query.replace(/[<>&]/g, '') + '" into a search for ' + sources.join(', ') + '.');
} else {
  const admins = [...new Set(users.filter((u) => u.telegram_user_id && u.active !== false && String(u.role || '').toLowerCase().trim() === 'admin')
    .map((u) => String(u.telegram_user_id).trim()))];
  for (const row of watch.filter((r) => r.active === true || String(r.active).toLowerCase() === 'true')) {
    const t = targets(row);
    const n = num(row.per_source, DEFAULT_PER_SOURCE);
    for (const s of SOURCES.filter((x) => t[x])) {
      plans.push({ kind: 'refs', mode: 'weekly', label: clean(row.brand), query: said(s, t[s]), source: s, ...call(s, t[s], n),
        keep_n: n, brand: clean(row.brand), niche: clean(row.niche), chat_ids: admins, found_for: 'weekly scan' });
    }
  }
  for (const a of audiences.filter((r) => r.active === true || String(r.active).toLowerCase() === 'true')) {
    const v = parseInt(clean(a.per_source), 10);
    plans.push(...audienceCalls(a, Number.isFinite(v) && v > 0 ? Math.min(v, MAX_AUDIENCE) : MAX_AUDIENCE,
      { mode: 'weekly', chat_ids: admins, found_for: 'weekly scan' }));
  }
}
return plans.slice(0, MAX_CALLS).map((p) => ({ json: { ...p, max_usd: p.max_usd || MAX_USD, timeout_s: 240 } }));

// n8n Code node "Read the Results" in "Reel Factory: Find References" (mode: Run Once for All Items).
// Input: one "Ask Apify" answer per planned call, in the same order as "Plan the Searches" ({ statusCode, body } with the run's
// dataset items as body, or { error } when the call failed). Output: one item per reference video found, in the columns of
// dtj_reel_library (videos only: an item without a direct video link is left out; a trending sound is the one row without one),
// then always one marker item { marker: true, url: '', found, by_audience, problems } with the counts and what failed for
// "Write the Digest". An audience scan's reels (source "audience") carry the audience, comments, the audio's name, the creator's
// followers when "profiles" gave them, views per follower and comments per view; they are ranked by views per follower (reels
// with a follower count first), then views.
// Field names: the picked actors and their fallbacks (refs_plan.js), as in the sample outputs on their Apify Store pages.
const plans = $('Plan the Searches').all().map((i) => i.json || {});
const answers = $input.all().map((i) => i.json || {});
const now = new Date();
const str = (v) => (v == null ? '' : String(v)).trim();
const first = (...vals) => { for (const v of vals) if (v != null && String(v).trim() !== '') return v; return null; };
const count = (...vals) => { const v = first(...vals); const n = Number(v); return v == null || !Number.isFinite(n) ? null : Math.round(n); };
const https = (u) => (/^https:\/\/[^\s"<>]+$/i.test(str(u)) ? str(u) : '');
const days = (start) => {
  if (start == null || start === '') return null;
  const t = typeof start === 'number' || /^\d{9,13}$/.test(String(start)) ? new Date(Number(start) * (String(start).length > 11 ? 1 : 1000))
    : new Date(String(start).length === 10 ? String(start) + 'T00:00:00Z' : String(start));
  return Number.isNaN(t.getTime()) ? null : Math.max(0, Math.floor((now - t) / 86400000));
};
const iso = (v) => {
  if (v == null || v === '') return '';
  const t = typeof v === 'number' || /^\d{9,13}$/.test(String(v)) ? new Date(Number(v) * (String(v).length > 11 ? 1 : 1000)) : new Date(String(v));
  return Number.isNaN(t.getTime()) ? str(v).slice(0, 30) : t.toISOString();
};

function instagram(x) {
  if (x.productType && !['clips', 'igtv', 'feed'].includes(x.productType) && !x.videoUrl) return null;
  const music = x.musicInfo || {};
  const song = str(first(music.song_name, music.title)), artist = str(first(music.artist_name, music.display_artist));
  return { url: https(x.url) || (x.shortCode ? 'https://www.instagram.com/reel/' + x.shortCode + '/' : ''), video_url: https(x.videoUrl),
    caption: str(x.caption), views: count(x.videoPlayCount, x.igPlayCount, x.videoViewCount), likes: count(x.likesCount),
    comments: count(x.commentsCount), username: str(x.ownerUsername).toLowerCase(),
    audio_name: song ? song + (artist ? ' · ' + artist : '') : '',
    owner: str(first(x.ownerFullName, x.ownerUsername)), posted_at: iso(x.timestamp), days_running: null };
}
function pinterest(x) {
  if (x.isVideo === false) return null;   // silentflow returns image pins too
  return { url: https(x.url), video_url: https(first(x.mp4Url, x.videoUrl, x.hlsUrl)), caption: str(first(x.title, x.description, x.altText)),
    views: count(x.viewCount), likes: count(x.saveCount, x.likeCount, x.saves),
    owner: str(first(x.creatorUsername, x.pinnerUsername, (x.pinner || {}).username)), posted_at: iso(x.createdAt), days_running: null };
}
function meta(x) {
  const snap = x.snapshot || {};
  const vids = [].concat(x.videoUrls || [], (snap.videos || []).map((v) => first(v.videoHdUrl, v.video_hd_url, v.videoSdUrl, v.video_sd_url)),
    (snap.cards || []).map((c) => first(c.videoHdUrl, c.video_hd_url, c.videoSdUrl, c.video_sd_url)));
  const id = str(first(x.adArchiveId, x.adArchiveID, x.ad_archive_id));
  const start = first(x.startDate, x.start_date, x.startDateFormatted);
  return { url: https(x.adLibraryUrl) || (id ? 'https://www.facebook.com/ads/library/?id=' + id : ''), video_url: https(vids.find(Boolean)),
    caption: str(first(x.bodyText, (snap.body || {}).text, x.title, snap.title)), views: null, likes: null,
    owner: str(first(x.pageName, snap.page_name, x.page_name)), posted_at: iso(start), days_running: days(start) };
}
function trending(x) {   // one trending sound (s_actors/instagram-trending-audio): its page is the link, there is no video
  const title = str(x.title), artist = str(first(x.artist, x.artistUsername));
  const facts = [str(first(x.reelsCountText, x.reelsCount != null ? x.reelsCount + ' reels' : '')), x.isTrending ? 'trending in India' : '',
    x.isOriginalAudio ? 'original audio' : 'song', x.topReelUrl ? 'top reel ' + str(x.topReelUrl) : ''].filter(Boolean).join('; ');
  return { url: https(first(x.audioUrl, x.url)), video_url: '', caption: title + (artist ? ' · ' + artist : '') + (facts ? ' (' + facts + ')' : ''),
    audio_name: title + (artist ? ' · ' + artist : ''), views: null, likes: null, owner: artist, posted_at: iso(x.newestReelAt), days_running: null };
}
const READ = { instagram, pinterest, meta, audience: instagram, trending_audio: trending };

const answerOf = (i) => {
  const a = answers[i] || {};
  let body = a.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* kept as text */ } }
  return { a, body, status: Number(a.statusCode || 0) };
};
const problems = [];
const failed = (plan, a, body, status) => {
  const why = (body && body.error && (body.error.message || body.error.type)) || (a.error && (a.error.message || a.error)) || (status ? 'HTTP ' + status : 'no answer');
  problems.push(plan.source + ' ' + (plan.query || plan.label || '') + ': ' + String(why).replace(/Bearer\s+\S+/gi, 'Bearer ***').slice(0, 160));
};

// the creators' followers first (kind "profiles"), so every reel of theirs gets views per follower
const followers = {};
plans.forEach((plan, i) => {
  if (plan.kind !== 'profiles') return;
  const { a, body, status } = answerOf(i);
  if (a.error || !Array.isArray(body)) { failed(plan, a, body, status); return; }
  for (const x of body) {
    const n = count(x && x.followersCount, x && x.followers);
    if (x && x.username && n) followers[str(x.username).toLowerCase()] = n;
  }
});

const out = [];
const seen = new Set();
const byAudience = {};
plans.forEach((plan, i) => {
  if (plan.kind === 'profiles') return;
  const { a, body, status } = answerOf(i);
  if (a.error || !Array.isArray(body)) { failed(plan, a, body, status); return; }
  const read = READ[plan.source];
  let rows = body.map((x) => (x && typeof x === 'object' && read ? read(x) : null))
    .filter((r) => r && r.url && (r.video_url || plan.source === 'trending_audio'));
  if (plan.source === 'meta') rows.sort((p, q) => (q.days_running || 0) - (p.days_running || 0));
  if (plan.source === 'audience') rows.sort((p, q) => (q.views || 0) - (p.views || 0));
  rows = rows.slice(0, plan.keep_n || rows.length);
  const aud = plan.source === 'audience' || plan.source === 'trending_audio';
  for (const r of rows) {
    const key = r.url + '|' + (plan.audience || '');
    if (seen.has(key)) continue;
    seen.add(key);
    const f = r.username ? followers[r.username] || null : null;
    out.push({ source: plan.source, url: r.url, video_url: r.video_url, brand: plan.brand || (aud && r.username ? '@' + r.username : r.owner),
      niche: plan.niche || '', caption: r.caption.slice(0, 2000), views: r.views, likes: r.likes, days_running: r.days_running,
      posted_at: r.posted_at, query: str(plan.query).slice(0, 300), actor: plan.actor, found_at: now.toISOString(), found_for: plan.found_for || '',
      keep: '', kept_by: '', kept_at: '', audience: plan.audience || '', audio_name: (r.audio_name || '').slice(0, 300),
      comments: aud && r.comments != null ? r.comments : null, followers: f,
      views_per_follower: f && r.views != null ? Math.round((r.views / f) * 1000) / 1000 : null,
      comments_per_view: aud && r.views && r.comments != null ? Math.round((r.comments / r.views) * 1e6) / 1e6 : null,
      link_key: key });
    if (plan.source === 'audience') byAudience[plan.audience] = (byAudience[plan.audience] || 0) + 1;
  }
  if (!rows.length && !body.length) problems.push(plan.source + ' ' + (plan.query || plan.label || '') + ': nothing found');
});
// an audience's reels by views per follower (those with a follower count first), then views
const score = (r) => [r.views_per_follower == null ? 1 : 0, -(r.views_per_follower || 0), -(r.views || 0)];
const order = (p, q) => { const a = score(p), b = score(q); for (let k = 0; k < a.length; k++) if (a[k] !== b[k]) return a[k] - b[k]; return 0; };
const refs = out.filter((r) => r.source !== 'audience');
const reels = out.filter((r) => r.source === 'audience').sort((p, q) => (p.audience < q.audience ? -1 : p.audience > q.audience ? 1 : order(p, q)));
const foundRefs = refs.filter((r) => r.source !== 'trending_audio').length;
return [...refs, ...reels, { marker: true, url: '', found: out.length, found_refs: foundRefs, by_audience: byAudience, problems }].map((json) => ({ json }));

// n8n Code node "Pick the New Ones" in "Reel Factory: Find References" (mode: Run Once for All Items).
// Input: the rows not yet in dtj_reel_library ("Only New Links" by link_key = "<link>|<audience>", so one reel is saved once per
// audience scan and once as a reference; one empty item when there are none). Output: those rows (the columns of
// dtj_reel_library only), or one { url: '' } item so "Anything New?" sends just the summary.
const COLS = ['source', 'url', 'video_url', 'brand', 'niche', 'caption', 'views', 'likes', 'days_running', 'posted_at', 'query', 'actor',
  'found_at', 'found_for', 'keep', 'kept_by', 'kept_at', 'audience', 'audio_name', 'comments', 'followers', 'views_per_follower',
  'comments_per_view', 'link_key'];
const NUMBERS = ['views', 'likes', 'days_running', 'comments', 'followers', 'views_per_follower', 'comments_per_view'];
const seen = new Set();
const out = [];
for (const it of $input.all()) {
  const r = it.json || {};
  const key = r.url + '|' + (r.audience || '');
  if (r.marker || !r.url || seen.has(key)) continue;
  seen.add(key);
  const row = {};
  for (const c of COLS) row[c] = r[c] == null ? (NUMBERS.includes(c) ? null : '') : r[c];
  out.push({ json: row });
}
return out.length ? out : [{ json: { url: '' } }];

// n8n Code node "Write the Digest" in "Reel Factory: Find References" (mode: Run Once for All Items).
// Input: the rows just saved in dtj_reel_library (each with its row id), or one empty item when nothing new was found.
// Output, per chat that gets it (the person who asked through the reel bot, or the active admins for the weekly scan):
//  - reference videos (kind "refs"): one summary message, then one message per new reference (at most MAX_SHOWN) with Keep / Skip
//    buttons. A button carries the bot's answer format "a:refs-<row id>:keep:<n>" (n8n/store-factory/bot_ask.py), so the reel bot's
//    "Reel Factory: Telegram Bot" saves the tap in dtj_bot_answers and "Match the Taps" here writes keep = yes / no on the row.
//  - an audience scan: one short message per audience, no buttons ("Audience scan <audience>: N reels saved, top 5 ..."), so the
//    reel watcher can build audiences/<slug>.md from the saved rows (source "audience" and "trending_audio", column audience).
// The messages go out through the reel bot ("DTJ Reel Bot"). A Pinterest pin's "likes" are its saves. Every item is
// { chat_id, text, summary, keep_data, skip_data } (HTML, text escaped).
const MAX_SHOWN = 15, TOP = 5;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const NAMES = { instagram: 'Instagram', pinterest: 'Pinterest', meta: 'Meta Ad Library' };
const AUDIENCE_KINDS = ['audience', 'profiles', 'trending'];
const big = (n) => {
  const v = Number(n);
  if (!Number.isFinite(v) || v <= 0) return '';
  return v >= 1e6 ? (v / 1e6).toFixed(1).replace(/\.0$/, '') + 'M' : v >= 1e3 ? (v / 1e3).toFixed(1).replace(/\.0$/, '') + 'k' : String(Math.round(v));
};
const clip = (s, n) => { const t = String(s || '').replace(/\s+/g, ' ').trim(); return t.length > n ? t.slice(0, n) + '…' : t; };

const saved = $input.all().map((i) => i.json || {}).filter((r) => r.id && r.url);
const results = $('Read the Results').all().map((i) => i.json || {});
const marker = results.find((r) => r.marker) || {};
const plans = $('Plan the Searches').all().map((i) => i.json || {});
const refPlans = plans.filter((p) => !AUDIENCE_KINDS.includes(p.kind));
const audPlans = plans.filter((p) => AUDIENCE_KINDS.includes(p.kind));
const ownProblem = (ps) => (msg) => ps.some((p) => String(msg).startsWith(p.source + ' ' + (p.query || p.label || '') + ':'));
const out = [];

// ---- reference videos with Keep / Skip
const refs = saved.filter((r) => r.source !== 'audience' && r.source !== 'trending_audio');
const refChats = [...new Set(refPlans.flatMap((p) => p.chat_ids || []).map(String).filter(Boolean))];
if (refPlans.length && refChats.length) {
  const first = refPlans[0];
  const what = first.mode === 'weekly' ? 'the weekly scan of the watchlist' : esc(first.label || first.query || 'your search');
  const perSource = {};
  for (const r of refs) perSource[r.source] = (perSource[r.source] || 0) + 1;
  const found = Number(marker.found_refs != null ? marker.found_refs : marker.found || 0);
  let head = refs.length
    ? '<b>' + refs.length + ' new reference video' + (refs.length === 1 ? '' : 's') + '</b> from ' + what + ' ('
      + Object.keys(perSource).map((s) => (NAMES[s] || s) + ' ' + perSource[s]).join(', ') + ').'
    : 'No new reference videos from ' + what + '.';
  if (found > refs.length) head += ' ' + (found - refs.length) + ' found were already in the library.';
  if (refs.length > MAX_SHOWN) head += ' The first ' + MAX_SHOWN + ' are below; all ' + refs.length + ' are saved in dtj_reel_library.';
  if (refs.length) head += '\nTap <b>Keep</b> to add one to the reel library (/reel and /remake can use it), <b>Skip</b> to leave it out.';
  const skipped = [...new Set(refPlans.flatMap((p) => p.skipped || []))].map((s) => (NAMES[s] || s) + ': nothing to search for there');
  const problems = [...(marker.problems || []).filter((m) => !ownProblem(audPlans)(m)), ...skipped].slice(0, 6);
  if (problems.length) head += '\n\nNotes: ' + problems.map((p) => esc(p)).join('; ') + '.';

  const order = { meta: 0, instagram: 1, pinterest: 2 };
  const shown = refs.slice().sort((a, b) => (order[a.source] ?? 3) - (order[b.source] ?? 3)
    || Number(b.days_running || 0) - Number(a.days_running || 0) || Number(b.views || 0) - Number(a.views || 0)).slice(0, MAX_SHOWN);
  for (const chat of refChats) {
    out.push({ json: { chat_id: chat, text: head, summary: true, keep_data: '', skip_data: '' } });
    shown.forEach((r, i) => {
      const facts = [r.days_running ? 'running ' + r.days_running + ' days' : '', big(r.views) ? big(r.views) + ' views' : '',
        big(r.likes) ? big(r.likes) + (r.source === 'pinterest' ? ' saves' : ' likes') : ''].filter(Boolean).join(' · ');
      const caption = clip(r.caption, 220);
      const text = '<b>' + (i + 1) + '/' + shown.length + ' · ' + esc(NAMES[r.source] || r.source) + (r.brand ? ' · ' + esc(r.brand) : '') + '</b>\n'
        + (caption ? '"' + esc(caption) + '"\n' : '')
        + (facts ? facts + '\n' : '')
        + '<a href="' + esc(r.url) + '">Open it</a>' + (r.video_url ? ' · <a href="' + esc(r.video_url) + '">video file</a>' : '');
      out.push({ json: { chat_id: chat, text, summary: false, keep_data: 'a:refs-' + r.id + ':keep:0', skip_data: 'a:refs-' + r.id + ':keep:1' } });
    });
  }
}

// ---- audience scans: one short summary each, no buttons
const score = (r) => [r.views_per_follower == null ? 1 : 0, -(r.views_per_follower || 0), -(r.views || 0)];
const byScore = (p, q) => { const a = score(p), b = score(q); for (let k = 0; k < a.length; k++) if (a[k] !== b[k]) return a[k] - b[k]; return 0; };
for (const name of [...new Set(audPlans.map((p) => p.audience))]) {
  const mine = audPlans.filter((p) => p.audience === name);
  const reels = saved.filter((r) => r.source === 'audience' && r.audience === name).sort(byScore);
  const sounds = saved.filter((r) => r.source === 'trending_audio' && r.audience === name);
  const found = Number((marker.by_audience || {})[name] || 0);
  const from = mine.filter((p) => p.kind === 'audience').map((p) => p.query).join(', ');
  let text = '<b>Audience scan ' + esc(name) + '</b>: ' + reels.length + ' reel' + (reels.length === 1 ? '' : 's') + ' saved'
    + (found > reels.length ? ' (' + (found - reels.length) + ' more were already in the library)' : '') + (from ? ', from ' + esc(from) : '') + '.';
  if (reels.length) {
    text += '\nTop ' + Math.min(TOP, reels.length) + (reels.some((r) => r.views_per_follower != null) ? ' by views per follower' : ' by views') + ':';
    reels.slice(0, TOP).forEach((r, i) => {
      const facts = [big(r.views) ? big(r.views) + ' views' : '', r.views_per_follower != null ? r.views_per_follower.toFixed(1) + '× followers' : '',
        r.comments_per_view != null ? (r.comments_per_view * 100).toFixed(2) + '% comments' : '', r.audio_name ? 'audio ' + clip(r.audio_name, 50) : '']
        .filter(Boolean).join(' · ');
      text += '\n' + (i + 1) + '. <a href="' + esc(r.url) + '">' + esc(r.brand || 'reel') + '</a>' + (facts ? ' · ' + esc(facts) : '');
    });
  }
  if (sounds.length) text += '\nTrending audio in India: ' + sounds.slice(0, TOP).map((r) => esc(clip(r.audio_name || r.caption, 60))).join('; ') + '.';
  text += '\nRows: dtj_reel_library, audience "' + esc(name) + '" (audiences/' + esc(mine[0].slug || '') + '.md).';
  const problems = (marker.problems || []).filter(ownProblem(mine)).slice(0, 4);
  if (problems.length) text += '\nNotes: ' + problems.map((p) => esc(p)).join('; ') + '.';
  for (const chat of [...new Set(mine.flatMap((p) => p.chat_ids || []).map(String).filter(Boolean))]) {
    out.push({ json: { chat_id: chat, text, summary: true, keep_data: '', skip_data: '' } });
  }
}
return out;

// n8n Code node "Match the Taps" in "Reel Factory: Find References" (mode: Run Once for All Items).
// The Keep / Skip buttons under each reference carry "a:refs-<library row id>:keep:<0 Keep | 1 Skip>"; the reel bot's workflow
// writes every tap into dtj_bot_answers (job refs-<id>, key keep, choice, by, at). Here: the last tap per reference
// from the last two days (older taps were recorded by earlier runs) -> one item per reference for "Record the Choice".
const WINDOW_MS = 2 * 24 * 3600 * 1000;
const since = new Date(Date.now() - WINDOW_MS).toISOString().slice(0, 19);
const last = {};
for (const it of $input.all()) {
  const r = it.json || {};
  const m = String(r.job || '').match(/^refs-(\d{1,12})$/);
  if (!m || String(r.key || '') !== 'keep') continue;
  const at = String(r.at || '').slice(0, 19);
  if (!at || at < since) continue;
  const choice = String(r.choice || '');
  const label = String(r.value || '').trim().toLowerCase();
  const keep = choice === '0' || (choice === '' && label === 'keep') ? 'yes' : choice === '1' || (choice === '' && label === 'skip') ? 'no' : '';
  if (!keep) continue;
  const prev = last[m[1]];
  if (prev && (prev.at > at || (prev.at === at && prev.id > Number(r.id || 0)))) continue;
  last[m[1]] = { at, id: Number(r.id || 0), keep, by: String(r.by || '').trim() || 'someone on the DTJ bot' };
}
return Object.keys(last).map((id) => ({ json: { row_id: Number(id), keep: last[id].keep, kept_by: last[id].by, kept_at: last[id].at + 'Z' } }));
